Task: Add the "Add to my picks" button to the book page. Use addPick from the picks store (features/picks/store/picksStore.ts) and the Button component (library/components/Button.tsx). The page needs 'use client' and React state for the status message.

Spec excerpt (SPEC.md):
BK-2: An available book has an "Add to my picks" button; pressing it adds the book to the member's picks and a status message says "Added to your picks".

BK-3: A book that is on loan says "On loan" and cannot be picked (no "Add to my picks" button, or a disabled one).

File features/book/pages/BookPage.tsx:
```tsx
// @line-base pages/DetailPage
// @line-route /books/:id
import Link from 'next/link';
import { DetailPage } from '../../../library/pages/DetailPage';
import books from '../../../library/fixtures/books.json';

type Book = { id: string; title: string; author: string; genre: string; year: number; pages: number; summary: string; available: boolean };

export function BookPage({ params }: { params: { id: string } }) {
  const { id } = params;
  const item = (books as Book[]).find((entry) => entry.id === id);
  const back = <Link href="/">Back to Books</Link>;
  if (!item) {
    return <DetailPage title="Book not found" back={back} />;
  }
  return (
    <DetailPage title={item.title} back={back}>
      <p>{item.author}</p>
      <p>{item.genre}</p>
      <p>{String(item.year)}</p>
      <p>{String(item.pages)}</p>
      <p>{item.summary}</p>
      <p>{String(item.available)}</p>
    </DetailPage>
  );
}
```

